BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT price FROM products WHERE id = 5;   -- $10
-- ... B commits $15 ...
SELECT price FROM products WHERE id = 5;   -- still $10
COMMIT;

BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM doctors WHERE status = 'ON_CALL';
UPDATE doctors SET status = 'OFF' WHERE name = 'Alice';
COMMIT;  -- may fail: could not serialize access … → retry

BEGIN;
SELECT id FROM jobs WHERE status = 'pending'
ORDER BY created_at LIMIT 1 FOR UPDATE SKIP LOCKED;
UPDATE jobs SET status = 'done' WHERE id = $1;
COMMIT;
